const CK=CASE.map(c=>c.id);

// =================== สถานะ ===================
function newK(bg){const nm=()=>pick(FN)+' '+pick(LN);return{v:1,bg,yr:87,dist:pick(DIST),path:null,tier:0,pw:4,ins:0,off:0,anc:70,fame0:0,rep:{lamp:0,church:bg==='orphan'?15:0,glass:0,steam:bg==='dock'?15:0,cult:0,house:bg==='fallen'?10:0},fac:null,
 cases:[],cur:null,arts:[],rum:{},enc:{p:{},f:{},a:{},n:{},d:{},l:{}},lore:0,f:{},later:[],debt:0,home:0,friend:nm(),mentor:nm(),rival:nm(),awk:0,end:null,bookY:0}}
const capOf=t=>Math.round(18*Math.pow(2.15,t));
const needIns=t=>[1,2,2,3,3,4,5,6,7][Math.max(0,Math.min(8,t))];
const offPrice=t=>Math.round(80*Math.pow(2.6,t));
const has=(K,a)=>(K.arts||[]).includes(a)&&!(a==='doll'&&K.f.dollGone===S.age);
const P=K=>K.path?PATH[K.path]:null;
const tName=K=>K.path&&K.tier>0?PATH[K.path].t[K.tier-1]:'คนธรรมดา';
const offName=K=>K.path?PATH[K.path].o[Math.min(8,K.tier)]:'';
function sync(){const K=FG();if(!K)return;const cap=capOf(K.tier)*(has(K,'jade')?1.3:1);K.pw=Math.min(K.pw,cap);S.power=Math.round(K.pw);const mh=Math.round(60+K.tier*22+(K.path==='debt'?K.tier*12:0));if(S.maxHp<mh)S.maxHp=mh;
 S.mw.end=Math.round((K.endB||72)+K.tier*6);S.money=Math.max(0,Math.round(S.money||0))}
function anc(d){const K=FG();if(!K)return'';const old=K.anc;K.anc=cl(K.anc+d,0,K.lost?ancMax(K):100);const r=Math.round(K.anc-old);return r?` · ⚓ ${r>0?'+':''}${r}`:''}
function cash(v){S.money=Math.max(0,Math.round((S.money||0)+v));return` · 🪙 ${v>=0?'+':''}${fmt(Math.round(v))}`}
function rep(k,d){const K=FG();if(!K||!FAC[k])return'';K.rep[k]=cl((K.rep[k]||0)+d,-100,100);K.enc.f[k]=1;if(d>0)(FOE[k]||[]).forEach(o=>{K.rep[o]=cl((K.rep[o]||0)-Math.round(d*.4),-100,100)});return` · ${FAC[k].ic}${d>0?'+':''}${d}`}
function fame(d){S.fame=Math.max(0,Math.round((S.fame||0)+d));return d?` · ⭐ ${d>0?'+':''}${fmt(d)}`:''}
function hurt(f){const d=Math.round(S.maxHp*f);S.hp-=d;return` · 💔 −${d}`}
function pw(g){const K=FG();const cap=capOf(K.tier)*(has(K,'jade')?1.3:1),old=K.pw;K.pw=Math.min(cap,K.pw+g);sync();const d=Math.round(K.pw-old);return d>0?` · ✴️ +${fmt(d)}`:''}
function encAdd(k,id){const K=FG();if(K&&K.enc[k])K.enc[k][id]=1}
function legName(){try{const L=LS.get('murim_legacy',[])||[];const x=L.find(l=>l&&l.n);return x?x.n:null}catch(e){return null}}
function fight(ep,vsAnom){const K=FG(),p=P(K);let my=S.power*(p?p.atk:.6)*(vsAnom&&K.path==='bell'?1.25:1)*(has(K,'lamp')&&vsAnom?1.25:1)*(.75+rnd()*.5);return my>=ep}
function winP(ep,vsAnom){const K=FG(),p=P(K),m=S.power*(p?p.atk:.6)*(vsAnom&&K.path==='bell'?1.25:1)*(has(K,'lamp')&&vsAnom?1.25:1);return cl((m*1.25-ep)/(m*.5),0,1)}
const threat=K=>Math.max(8,capOf(Math.max(1,K.tier))*.55);

// =================== คิวเหตุการณ์ ===================
const QU=[];function queue(f){QU.push(f)}
let FL=0;function flush(){if(!QU.length||FL)return;FL=1;const go=()=>{if(!on()){QU.length=0;FL=0;return}if(choice._cur||modalOpen)return setTimeout(go,700);const f=QU.shift();if(typeof f==='function')try{f()}catch(e){console.error('fog ev',e)}if(QU.length)setTimeout(go,900);else FL=0};setTimeout(go,300)}
const C=(t,x,o)=>{try{setScene('fog')}catch(e){}try{const K=FG();if(K&&K.anc<25&&Array.isArray(o)&&o.length>=2&&rnd()<.45)o=o.concat([halOpt(K)])}catch(e){}return choice(t,x,o)};

