function evAwake(K){if(K.path||K.awk)return;K.awk=1;const L=PK.slice().sort(()=>rnd()-.5).slice(0,3);
 C('🌫️ ฝันที่ไม่ใช่ของคุณ',`คืนที่หมอกหนาที่สุดของปี คุณฝันว่ายืนอยู่ใต้หอระฆังที่ร้าวเป็นแปดเสี่ยง เสียงสามเสียงเรียกชื่อคุณจากในหมอก แต่ละเสียงยื่นของบางอย่างให้<br><span class="tag2">รับแล้วจะกลายเป็นผู้ถือตรา ธรณีที่ 1 · หลักยึดลด · กลับไปเป็นคนธรรมดาไม่ได้อีก</span>`,
  L.map(k=>{const p=PATH[k];return O(`${p.ic} ${p.n}`,()=>{K.path=k;K.tier=1;K.pw=Math.max(K.pw,capOf(1)*.4);K.off=1;encAdd('p',k);K.lore=Math.max(K.lore,1);sync();
   say(`${p.ic} <b>คุณตื่นขึ้นมาพร้อมตราธรณีที่ 1 — ${p.n}: ${p.t[0]}</b> ${p.d}${anc(-10)}`,'myth',true);try{island({big:1,ic:p.ic,h:'ตราธรณีที่ 1',t:p.n,kind:'gold',ms:5000})}catch(e){}feed(`📜 จุดแข็ง: ${p.st} · จุดอ่อน: ${p.wk}`);render()},`${p.st} · จุดอ่อน: ${p.wk}`,.33)}).concat([
  O('🙅 ไม่รับอะไรเลย ตื่นขึ้นมา',()=>{K.f.refuse=1;say(`☕ คุณบังคับตัวเองให้ตื่น เหงื่อท่วมตัว เสียงในหมอกเงียบไป…สักพัก${anc(5)}`,'');K.later.push([S.age+R(3,6),'reawake'])},'ยังเป็นคนธรรมดาต่อไป (อาจมีโอกาสอีกครั้ง)',.05)]))}

