 <div class="fgClues">${c.cl.map((k,i)=>`<button class="${k.x?'x':''}" onclick="fogBdT(${i})">${TCN[k.c].split(' ')[0]} คนร้าย${k.v}<small>${esc(k.src)}</small></button>`).join('')||'<i>ไม่มีเบาะแสเลย</i>'}</div>
