 const adj=i=>{const r=Math.floor(i/4),c0=i%4;let n=0;for(let dr=-1;dr<=1;dr++)for(let dc=-1;dc<=1;dc++){if(!dr&&!dc)continue;const rr=r+dr,cc=c0+dc;if(rr<0||cc<0||rr>3||cc>3)continue;if(E.includes(rr*4+cc))n++}return n};
